-- Source rows for production.FactReserve: the logic of the table.
-- Generated by `python -m fde render` from models/gold/production/FactReserve.sql. Do not edit: change the spec and render again.

IF SCHEMA_ID('stage') IS NULL
    EXEC('CREATE SCHEMA [stage]');
GO

CREATE OR ALTER VIEW [stage].[FactReserveSource]
AS
with

reserve as (

    select * from [lh_silver].[dbo].[materialreserve]

),

facility as (

    select * from [facilities].[DimFacility]

),

material as (

    select * from [production].[DimMaterial]

),

commodity_material as (

    select * from [production].[DimMaterial]

),

data_source as (

    select * from [facilities].[DimDataSource]

)

select
    reserve.MaterialReserve_BK,
    coalesce(facility.DimFacility_SK, -1) as DimFacility_SK,
    coalesce(material.DimMaterial_SK, -1) as DimMaterial_SK,
    coalesce(commodity_material.DimMaterial_SK, -1) as CommodityDimMaterial_SK,
    coalesce(data_source.DimDataSource_SK, -1) as DimDataSource_SK,
    reserve.ReserveYear,
    reserve.MineralValueTonnes,
    reserve.CommodityValueTonnes,
    reserve.GradePartsPerMillion
from reserve
left join facility
    on facility.Facility_BK = reserve.Facility_BK
left join material
    on material.Material_BK = reserve.Material_BK
left join commodity_material
    on commodity_material.Material_BK = reserve.CommodityMaterial_BK
left join data_source
    on data_source.DataSource_BK = reserve.DataSource_BK
GO
